def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    bits = 1                           # bit s is set ⇔ sum s is reachable
    for x in nums:
        bits |= bits << x              # every old sum, and every old sum + x
    return bool(bits >> (total // 2) & 1)

