def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    S = total // 2
    dp = [[False] * (S + 1) for _ in range(len(nums) + 1)]
    dp[0][0] = True                    # dp[i][s]: the first i numbers can make s
    for i, x in enumerate(nums, 1):
        for s in range(S + 1):
            dp[i][s] = dp[i - 1][s] or (s >= x and dp[i - 1][s - x])
    return dp[-1][S]

